-- Aula 07 · Data Collection and Storage · 28/11/2026 · Pydantic, contratos e testes, com retomada da Aula 06.
-- Usa as tabelas/RPCs existentes no Supabase do aulas_senac. Não execute o schema destrutivo.
-- Reexecução preserva IDs; recusa alterar sala iniciada ou com participantes.
-- O token do professor entra pelo marcador __QUIZ_HOST_TOKEN__, trocado pelo valor do .env na aplicação
-- (npm run quiz:dc-aula07:apply, que chama scripts/quiz_db.mjs com --token-env DCS_HOST_TOKEN).
begin;
select pg_advisory_xact_lock(hashtext('mack-dcs-a07-2026-2'));
do $$ begin if exists (select 1 from quiz_sessions where slug='mack-dcs-a07-2026-2' and (estado <> 'lobby' or pergunta_atual <> 0)) or exists (select 1 from quiz_players where session_slug='mack-dcs-a07-2026-2') then raise exception 'Sala já iniciada ou com participantes: seed cancelado para preservar a rodada.'; end if; end $$;
insert into quiz_sessions (slug,titulo,periodo) values ('mack-dcs-a07-2026-2','Aula 07 — Quiz: Pydantic, contratos e testes','2026-2') on conflict (slug) do update set titulo=excluded.titulo;
with novas as (
  insert into quiz_questions (session_slug,ordem,enunciado,alternativas,segundos,tema,secao,peso) values
  ('mack-dcs-a07-2026-2', 1, 'No pipeline da Aula 06, o armazenador grava o lote no ClickHouse e só depois dá ack no RabbitMQ. O processo cai entre o INSERT e o ack. O que acontece com essas leituras e o que evita linhas duplicadas na tabela?', '["A mensagem se perde, porque o broker a considera entregue ao sair da fila; o simulador repõe a leitura no ciclo seguinte.", "O broker move o lote inteiro para a DLQ, e o transformador o republica depois com novos valores de event_id.", "As mensagens voltam para a fila e são gravadas de novo; o token por lote e o ReplacingMergeTree deduplicam.", "O ClickHouse recusa o segundo INSERT por chave duplicada, já que o ORDER BY impõe unicidade na tabela."]'::jsonb, 90, 'Entrega at-least-once e deduplicação', 'Aula 06 — garantias de entrega, ReplacingMergeTree e token por lote', 1),
  ('mack-dcs-a07-2026-2', 2, 'O transformador pode levar uma leitura inválida até leituras.dlq de duas formas: publicar em iot.dlx com o cabeçalho x-motivo ou chamar basic_nack(requeue=False). Qual delas atende ao requisito de rastreabilidade (RNF-02) da Aula 07?', '["Publicar em iot.dlx com x-motivo e dar ack na original, porque o nack só deixa o x-death com reason: rejected.", "Chamar basic_nack(requeue=False), porque o x-death registra qual regra do contrato falhou na validação.", "Qualquer uma, pois as duas mensagens chegam em leituras.dlq com o mesmo conjunto de cabeçalhos.", "Chamar basic_nack(requeue=True), para que o transformador valide a mensagem de novo antes de desistir."]'::jsonb, 90, 'DLQ com motivo', 'Aula 07 — seção 4.2, DLQ no RabbitMQ e auditoria no ClickHouse', 1),
  ('mack-dcs-a07-2026-2', 3, 'Para reduzir a latência, um colega muda o armazenador da Aula 06 para fazer um INSERT por leitura no ClickHouse. Com doze sensores a uma leitura por segundo, qual consequência a Aula 06 prevê e qual é a correção?', '["Cada parte pequena é lida em paralelo e as consultas aceleram; o armazenador pode ficar como está.", "O TTL deixa de valer nas partes novas; a correção é trocar a partição mensal por uma partição diária.", "A deduplicação passa a ser exata a cada INSERT; o ReplacingMergeTree vira redundante e pode sair.", "Cada INSERT cria uma parte, os merges não acompanham e surge too many parts; o lote fecha por tamanho ou tempo."]'::jsonb, 90, 'Inserção em lote no ClickHouse', 'Aula 06 — partes, merges e inserção em lote', 1),
  ('mack-dcs-a07-2026-2', 4, 'Um sensor antigo da estufa mede em Fahrenheit, mas o firmware passou a rotular a leitura como C. O valor 76,28 é um float válido. Que regra do contrato LeituraBruta detecta esse caso?', '["Declarar temperatura como StrictFloat, pois o modo strict recusa números fora da unidade declarada.", "Um model_validator que converte para °C e aplica a faixa física, apoiado no cadastro de unidade do sensor.", "Configurar extra=\"forbid\", pois o rótulo trocado chega como um campo que o modelo não declara.", "Restringir unidade_temperatura com Literal[\"C\", \"F\"], pois o rótulo errado vira unidade desconhecida."]'::jsonb, 90, 'Faixa física e unidade', 'Aula 07 — seção 3 e exemplo numérico 1 (seção 2.5)', 1),
  ('mack-dcs-a07-2026-2', 5, 'Na borda do scraping de books.toscrape.com, todo valor extraído do HTML chega como texto, como "£47.82" e "Four". Um colega propõe ConfigDict(strict=True) no contrato Livro. Qual é o efeito?', '["Ganho de segurança sem custo, pois o strict só recusa valores que o modo lax também recusaria.", "O contrato recusaria praticamente todos os livros; ali o caminho é lax com validadores mode=\"before\".", "O strict converteria \"£47.82\" em Decimal sozinho, o que dispensa o validador de preço do contrato.", "Nenhum efeito, porque o strict só vale em model_validate_json e a extração usa model_validate."]'::jsonb, 90, 'Modo lax e modo strict', 'Aula 07 — seção 6.2, coerção lax e strict', 1),
  ('mack-dcs-a07-2026-2', 6, 'A API PTAX do BCB passa a devolver um campo novo e inofensivo. Qual configuração do contrato CotacaoPtax a aula adota e por quê?', '["extra=\"forbid\", para que a coleta pare e o grupo atualize o contrato antes de gravar qualquer cotação.", "extra=\"allow\", para guardar o campo novo no objeto e gravá-lo no bronze sem revisão do contrato.", "extra=\"ignore\", com um teste de contrato separado que compara as chaves recebidas e alerta sobre as novas.", "extra=\"ignore\" sem teste adicional, pois descartar campos desconhecidos em silêncio não custa nada."]'::jsonb, 90, 'Campo desconhecido', 'Aula 07 — seção 6.3, ConfigDict(extra=...)', 1),
  ('mack-dcs-a07-2026-2', 7, 'Uma coleta de livros gera 37 rejeições. Para o relatório de rejeições apontar a causa, qual informação de erro.errors() deve servir de chave de contagem?', '["O campo msg, porque o texto descreve o problema numa linguagem que a persona entende.", "O campo input, porque o valor recebido mostra exatamente o registro que falhou.", "A posição do registro no lote, porque ela indica a linha que precisa ser reprocessada.", "O par loc e type, porque type é o código estável da regra e loc indica o campo."]'::jsonb, 90, 'Erros por registro', 'Aula 07 — seção 6.5, ValidationError e registro de erros', 1),
  ('mack-dcs-a07-2026-2', 8, 'O teste da regra "medido_em no futuro" usa a leitura de exemplo da Aula 06, datada de 14/11/2026, e falhou ao rodar em 03/10/2026. Qual ajuste a aula aplica?', '["Passar o instante agora pelo contexto de validação, para que o teste fixe o relógio e rode igual em qualquer data.", "Remover a regra de medido_em no futuro, pois relógios de sensores divergem e a regra só gera falso positivo.", "Ampliar a tolerância de 5 minutos para 60 dias, cobrindo a distância entre a leitura e a data do teste.", "Marcar o teste com @pytest.mark.integracao, para que ele rode só no CI, onde o relógio é sincronizado."]'::jsonb, 90, 'Relógio fixo no teste', 'Aula 07 — seções 6.5 e 13, contexto de validação', 1),
  ('mack-dcs-a07-2026-2', 9, 'O teste de contrato da PTAX reproduz um cassete gravado há dois meses e continua verde. Na produção, todas as cotações caem em quarentena porque o BCB renomeou cotacaoVenda. O que a aula recomenda?', '["Trocar o modo do pytest-recording para new_episodes, acrescentando a resposta nova ao cassete atual.", "Teste ao vivo agendado com --record-mode=all, regravação quando surge rejeição nova e revisão do diff do YAML.", "Substituir o cassete por um dict escrito à mão, atualizado pelo grupo sempre que a API mudar de formato.", "Retirar --block-network do CI, para que o teste de contrato consulte a API real a cada pull request."]'::jsonb, 90, 'Cassete desatualizado', 'Aula 07 — seção 8.4, quando regravar o cassete', 1),
  ('mack-dcs-a07-2026-2', 10, 'O grupo precisa provar que o armazenador grava em iot.leituras e que leituras inválidas chegam em iot.leituras_rejeitadas. Um teste com o cliente do ClickHouse simulado já passa. Qual evidência a pirâmide da aula pede, sem deixar a suíte lenta?', '["Mais testes de unidade com o cliente simulado, um por coluna, já que a base da pirâmide aponta o defeito exato.", "Um teste ponta a ponta com docker compose subido à mão, conferindo as tabelas no clickhouse-client ao final.", "Integração com a imagem clickhouse-server:latest e fixture de escopo function, para isolar cada teste.", "Integração com ClickHouseContainer em tag fixa e a DDL da Aula 06, fixture de escopo session e marcador integracao."]'::jsonb, 90, 'Testcontainers na pirâmide', 'Aula 07 — seções 7, 9.3 e 9.6, pirâmide e escopo da fixture', 2)
  on conflict (session_slug,ordem) do update set enunciado=excluded.enunciado, alternativas=excluded.alternativas, segundos=excluded.segundos, tema=excluded.tema, secao=excluded.secao, peso=excluded.peso
  returning id,ordem
)
insert into quiz_answer_key (question_id,correta,explicacao)
select n.id,g.correta,g.explicacao from novas n join (values
  (1, 2, 'Com ack manual depois do INSERT, a entrega é at-least-once: se o processo cai antes do ack, o RabbitMQ devolve as mensagens à fila com redelivered=True, e o lote é gravado de novo. O efeito exactly-once vem da escrita idempotente: o token por lote descarta o INSERT repetido dentro da janela de deduplicação, e o ReplacingMergeTree colapsa linhas com a mesma chave (device_id, medido_em) no merge. O ORDER BY do ClickHouse ordena o disco e não impõe unicidade.'),
  (2, 0, 'As duas formas levam a mensagem a leituras.dlq. Na execução de 03/10/2026, a publicada em iot.dlx trazia x-motivo = umidade_fora_da_faixa; a recusada com nack trazia só o x-death, com reason: rejected, fila e routing key, sem dizer qual regra falhou. O RNF-02 exige o motivo, que sai do erro do Pydantic. Com requeue=True, a mensagem inválida voltaria à fila e falharia de novo.'),
  (3, 3, 'Cada INSERT cria uma parte no MergeTree. Doze leituras por segundo viram doze partes por segundo, os merges em segundo plano não acompanham e o servidor passa a recusar com too many parts. A documentação do ClickHouse recomenda lotes de pelo menos 1.000 linhas; com poucos sensores, o armazenador fecha o lote por tamanho ou por tempo, o que vier primeiro, ou usa async_insert.'),
  (4, 1, 'O tipo float aceita 76,28 em qualquer unidade, e Literal["C", "F"] aceita o rótulo C. O model_validator converte para Celsius e aplica a faixa física: 76,28 passa de 60 °C e é recusado. Um valor em F até 60 (temperatura real até 15,6 °C) ainda cai na faixa, como mostrou o exemplo numérico 1; só o cadastro com a unidade esperada de cada device_id fecha essa lacuna.'),
  (5, 1, 'No modo strict, o tipo da entrada precisa coincidir com o declarado, e o HTML só entrega texto: "4" não vira int nem "47.82" vira Decimal, então praticamente todo livro seria recusado. Na borda do scraping, o caminho é o modo lax com validadores mode="before" que tiram o £ e convertem "Four" em 4, deixando o Field conferir o resultado. O strict faz sentido onde o grupo controla o produtor, como o simulador de sensores.'),
  (6, 2, 'O BCB é um produtor externo. Com forbid, a coleta inteira pararia no dia em que a API acrescentasse um campo inofensivo; com allow, o campo entraria no bronze sem revisão. A aula usa ignore, que também descarta paridadeCompra e paridadeVenda, e mantém um teste de contrato que compara as chaves recebidas com os campos conhecidos e alerta sobre as novas. Ignorar sem esse teste esconde a mudança da fonte.'),
  (7, 3, 'O type é o código estável da regra (timezone_aware, string_pattern_mismatch, extra_forbidden) e o loc diz em qual campo ela falhou. "37 rejeições por timezone_aware em coletado_em" aponta direto para o coletor que perdeu o fuso. O msg é texto e muda com a versão e com a mensagem do validador; input e posição servem para reprocessar, não para contar causas.'),
  (8, 0, 'Com o relógio real, a leitura de 14/11/2026 parecia futura em 03/10/2026, e o teste dependia da data em que rodava. O exemplo da aula passa agora pelo contexto de validação (model_validate_json(corpo, context={"agora": AGORA}), lido em info.context no model_validator), e o teste fixa o instante. Remover a regra ou alargar a tolerância enfraquece o contrato; mover o teste de camada não resolve a dependência do relógio.'),
  (9, 1, 'O cassete congela a resposta do dia da gravação, por isso o PR continua verde. A aula combina cassete no PR com um teste de contrato ao vivo, marcado e executado com --record-mode=all num job agendado, regravação quando a produção registra uma rejeição nova ou o cassete passa da idade definida, e revisão do diff do YAML. new_episodes mistura respostas de dias diferentes, e um dict escrito à mão testa o que o grupo imagina da API.'),
  (10, 3, 'O cliente simulado prova que o código chama insert, e não que a tabela existe ou que as colunas batem com a DDL. O teste de integração sobe o ClickHouse real (clickhouse/clickhouse-server:26.8.15.10, a tag do compose da Aula 06) com a DDL aplicada. A fixture de escopo session paga a subida de cerca de 5,9 s uma vez por execução, e o marcador integracao permite rodar a base sem Docker. latest muda o comportamento sem mudança de código, e o escopo function multiplica a subida pelo número de testes.')
) as g(ordem,correta,explicacao) on g.ordem=n.ordem
on conflict (question_id) do update set correta=excluded.correta, explicacao=excluded.explicacao;
insert into quiz_host_tokens (session_slug,token) values ('mack-dcs-a07-2026-2','__QUIZ_HOST_TOKEN__') on conflict (session_slug) do update set token=excluded.token;
do $$ begin if (select count(*) from quiz_questions where session_slug='mack-dcs-a07-2026-2') <> 10 then raise exception 'A sala deve conter exatamente 10 perguntas'; end if; end $$;
commit;
